def create_post(site_id, wp_post_type, title, content, excerpt=None, slug=None, author_wp_user_id=None, status=None, **_extra):
    import json, os, datetime, re, time, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0552000" if __import__("os").path.isdir("./environment_mix/0552000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Auth (ambient): pick any active key, enforce rate limit per key
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available.")

    ops = _load("post_operations.json")

    def _parse_iso(s):
        if not s or not isinstance(s, str): return None
        try:
            if s.endswith("Z"): s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _check_rate_limit_and_touch_key():
        nonlocal api_keys
        # choose a key that is under limit (sliding 60s window)
        now_dt = datetime.datetime.utcnow()
        best = None
        best_count = None
        for k in active_keys:
            kid = k.get("id")
            limit = k.get("rate_limit_per_minute")
            if not isinstance(limit, int) or limit < 1:
                continue
            window_start = now_dt - datetime.timedelta(seconds=60)
            cnt = 0
            for o in ops:
                if not isinstance(o, dict): 
                    continue
                if o.get("api_key_id") != kid:
                    continue
                ts = _parse_iso(o.get("created_at"))
                if ts and ts >= window_start:
                    cnt += 1
            if cnt < limit:
                if best is None or cnt < best_count:
                    best, best_count = k, cnt
        if best is None:
            # Rate limited: do not enqueue operations
            return None, _err("RATE_LIMIT", "Rate limit exceeded for all active API keys.")
        # touch last_used_at
        for kk in api_keys:
            if isinstance(kk, dict) and kk.get("id") == best.get("id"):
                kk["last_used_at"] = now
                kk["updated_at"] = kk.get("updated_at") or now
        _save("api_keys.json", api_keys)
        return best, None

    api_key, rate_err = _check_rate_limit_and_touch_key()
    if rate_err:
        return rate_err

    # --- Input validation
    if not isinstance(site_id, str) or not re.match(r"^wps_[0-9A-HJKMNP-TV-Z]{26}$", site_id):
        return _err("VALIDATION_ERROR", "site_id is invalid.", field="site_id")
    if wp_post_type not in ("post", "page", "custom"):
        return _err("VALIDATION_ERROR", "wp_post_type is invalid.", field="wp_post_type")
    if not isinstance(title, str) or title.strip() == "":
        return _err("VALIDATION_ERROR", "title is required and must be non-empty.", field="title")
    if not isinstance(content, str):
        return _err("VALIDATION_ERROR", "content is required and must be a string.", field="content")
    if excerpt is not None and not isinstance(excerpt, str):
        return _err("VALIDATION_ERROR", "excerpt must be a string.", field="excerpt")
    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "slug must be a string.", field="slug")
    if author_wp_user_id is not None and not isinstance(author_wp_user_id, int):
        return _err("VALIDATION_ERROR", "author_wp_user_id must be an integer.", field="author_wp_user_id")
    if status is not None and status not in ("draft", "published", "scheduled"):
        return _err("VALIDATION_ERROR", "status is invalid.", field="status")

    # --- Resolve site
    sites = _load("wp_sites.json")
    site = next((s for s in sites if isinstance(s, dict) and s.get("id") == site_id), None)
    if not site:
        return _err("NOT_FOUND", "Site not found.", site_id=site_id)

    # --- Create post_operations row ALWAYS for create_post call
    def _ulid_like(prefix):
        # generate 26-char Crockford base32
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ts_ms = int(time.time() * 1000)
        # 48-bit time + 80-bit randomness -> 26 chars base32 (~130 bits).
        # We'll approximate with hashing for deterministic length.
        rnd = os.urandom(16)
        h = hashlib.sha256(str(ts_ms).encode("utf-8") + rnd).digest()
        num = int.from_bytes(h[:17], "big")  # 136 bits; we'll trim by base32 length
        chars = []
        for _ in range(26):
            chars.append(alphabet[num & 31])
            num >>= 5
        return prefix + "".join(reversed(chars))

    op_id = _ulid_like("op_")
    op_row = {
        "id": op_id,
        "site_id": site_id,
        "post_id": None,
        "operation": "create_post",
        "status": "queued",
        "request_payload": {
            "wp_post_type": wp_post_type,
            "title": title,
            "content_present": bool(content),
            "excerpt_present": bool(excerpt),
            "slug": slug,
            "author_wp_user_id": author_wp_user_id,
            "status": status or "draft",
        },
        "response_payload": None,
        "http_status": None,
        "error": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
        "api_key_id": api_key.get("id"),
        "latency_ms": None,
    }
    ops.append(op_row)
    _save("post_operations.json", ops)

    # If site not active: must NOT be used for outbound calls; log failed op
    if site.get("status") != "active":
        # transition queued -> running -> failed
        for o in ops:
            if o.get("id") == op_id:
                o["status"] = "running"
                o["started_at"] = now
                o["updated_at"] = now
        _save("post_operations.json", ops)

        err_obj = {"type": "SITE_INACTIVE", "message": "Site is not active; outbound WordPress calls are forbidden.", "site_status": site.get("status")}
        for o in ops:
            if o.get("id") == op_id:
                o["status"] = "failed"
                o["error"] = err_obj
                o["http_status"] = None
                o["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                o["updated_at"] = o["finished_at"]
                o["latency_ms"] = int((time.time() - t0) * 1000)
        _save("post_operations.json", ops)
        return _err("INVALID_TRANSITION", "Site is not active.", site_id=site_id, site_status=site.get("status"))

    # --- Simulate outbound WP REST create (offline): succeed and mint remote identifiers
    # transition queued -> running
    for o in ops:
        if o.get("id") == op_id:
            o["status"] = "running"
            o["started_at"] = now
            o["updated_at"] = now
    _save("post_operations.json", ops)

    # Load posts
    posts = _load("wp_posts.json")

    # Generate local post row id
    post_id = _ulid_like("wpp_")

    # Determine remote post id (unique per site)
    existing_wp_ids = set()
    for p in posts:
        if isinstance(p, dict) and p.get("site_id") == site_id and p.get("wp_post_id") is not None:
            existing_wp_ids.add(p.get("wp_post_id"))
    # Choose next id
    wp_post_id = 1
    if existing_wp_ids:
        try:
            wp_post_id = max(int(x) for x in existing_wp_ids if isinstance(x, int) or (isinstance(x, str) and str(x).isdigit())) + 1
        except Exception:
            wp_post_id = 1
            while wp_post_id in existing_wp_ids:
                wp_post_id += 1
    else:
        wp_post_id = 1

    # Enforce unique(site_id, wp_post_id) (should hold by construction)
    for p in posts:
        if isinstance(p, dict) and p.get("site_id") == site_id and p.get("wp_post_id") == wp_post_id:
            # extremely unlikely: pick another
            while wp_post_id in existing_wp_ids:
                wp_post_id += 1
            break

    # Map local status -> wp_status
    desired_local_status = status or "draft"
    wp_status = {"draft": "draft", "published": "publish", "scheduled": "future"}[desired_local_status]

    base_url = site.get("base_url") or ""
    wp_link = None
    if isinstance(base_url, str) and base_url.startswith("http"):
        # simple permalink style
        safe_slug = slug.strip() if isinstance(slug, str) and slug.strip() else f"{wp_post_type}-{wp_post_id}"
        wp_link = base_url.rstrip("/") + "/" + safe_slug.strip("/")

    remote_modified_at = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    last_synced_at = remote_modified_at

    new_post = {
        "id": post_id,
        "site_id": site_id,
        "wp_post_id": int(wp_post_id),
        "wp_post_type": wp_post_type,
        "slug": slug,
        "title": title,
        "content": content,
        "excerpt": excerpt,
        "author_wp_user_id": author_wp_user_id,
        "status": desired_local_status,          # MUST NOT remain sync_pending
        "wp_status": wp_status,
        "wp_link": wp_link,
        "remote_modified_at": remote_modified_at,
        "last_synced_at": last_synced_at,
        "last_error": None,
        "created_at": now,
        "updated_at": now,
    }

    # Upsert logic: if an identical mapping exists by (site_id, wp_post_id) update; else insert.
    upserted = False
    for p in posts:
        if isinstance(p, dict) and p.get("site_id") == site_id and p.get("wp_post_id") == new_post["wp_post_id"]:
            # update existing row
            p.update({k: v for k, v in new_post.items() if k != "id"})
            p["updated_at"] = now
            # keep existing id
            new_post["id"] = p.get("id")
            upserted = True
            break
    if not upserted:
        posts.append(new_post)
    _save("wp_posts.json", posts)

    # Update op with local post_id, response payload, success transition
    for o in ops:
        if o.get("id") == op_id:
            o["post_id"] = new_post["id"]
            o["response_payload"] = {
                "wp_post_id": new_post["wp_post_id"],
                "wp_status": new_post["wp_status"],
                "wp_link": new_post["wp_link"],
                "remote_modified_at": new_post["remote_modified_at"],
            }
            o["http_status"] = 201
            o["status"] = "succeeded"
            o["finished_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            o["updated_at"] = o["finished_at"]
            o["latency_ms"] = int((time.time() - t0) * 1000)
    _save("post_operations.json", ops)

    return {
        "post": new_post,
        "operation": next((o for o in ops if o.get("id") == op_id), None),
    }

def get_posts(site_id, wp_post_type=None, status=None, search=None, use_cache=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0552000" if __import__("os").path.isdir("./environment_mix/0552000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(v):
        if not v or not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    def _norm_str(x):
        if x is None:
            return None
        if not isinstance(x, str):
            return None
        return x

    # --- Validate inputs ---
    if not isinstance(site_id, str) or not re.match(r"^wps_[0-9A-HJKMNP-TV-Z]{26}$", site_id):
        return _err("VALIDATION_ERROR", "site_id must be a valid ULID with prefix 'wps_'.", field="site_id")

    if wp_post_type is not None:
        if not isinstance(wp_post_type, str) or wp_post_type not in ("post", "page", "custom"):
            return _err("VALIDATION_ERROR", "wp_post_type must be one of: post, page, custom.", field="wp_post_type")

    if status is not None:
        if not isinstance(status, str) or status not in ("draft", "published", "scheduled", "trashed", "sync_pending", "sync_error"):
            return _err("VALIDATION_ERROR", "status must be one of: draft, published, scheduled, trashed, sync_pending, sync_error.", field="status")

    if search is not None and not isinstance(search, str):
        return _err("VALIDATION_ERROR", "search must be a string.", field="search")

    if use_cache is None:
        use_cache = True
    if not isinstance(use_cache, bool):
        return _err("VALIDATION_ERROR", "use_cache must be a boolean.", field="use_cache")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    if sort_by is None:
        sort_by = "updated_at"
    if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "remote_modified_at", "last_synced_at", "title", "slug"):
        return _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, remote_modified_at, last_synced_at, title, slug.", field="sort_by")

    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "sort_order must be 'asc' or 'desc'.", field="sort_order")

    # --- Auth (ambient): must have an active API key; revoked => reject and do NOT create post_operations rows ---
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available.")

    # --- Rate limit enforcement: count recent post_operations by api_key_id ---
    ops = _load("post_operations.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    window_start = now_dt - datetime.timedelta(seconds=60)

    chosen_key = None
    chosen_count = None
    for k in active_keys:
        rl = k.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1 or rl > 6000:
            continue
        kid = k.get("id")
        cnt = 0
        for o in ops:
            if not isinstance(o, dict):
                continue
            if o.get("api_key_id") != kid:
                continue
            ts = _parse_dt_any(o.get("created_at"))
            if ts is not None and ts >= window_start:
                cnt += 1
        if cnt < rl:
            if chosen_key is None or cnt < chosen_count:
                chosen_key, chosen_count = k, cnt

    if chosen_key is None:
        return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=60)

    # Touch chosen key usage (observable dynamics) without creating invalid post_operations entries
    now_iso = _now_iso()
    for kk in api_keys:
        if isinstance(kk, dict) and kk.get("id") == chosen_key.get("id"):
            kk["last_used_at"] = now_iso
            kk["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # --- Site exists? ---
    sites = _load("wp_sites.json")
    site = None
    for s in sites:
        if isinstance(s, dict) and s.get("id") == site_id:
            site = s
            break
    if site is None:
        return _err("NOT_FOUND", "Site not found.", site_id=site_id)

    # --- If use_cache=false, attempt outbound refresh; blocked if site not active and MUST be logged as failed get_posts op ---
    performed_refresh = False
    if use_cache is False:
        performed_refresh = True
        # Create post_operations row operation='get_posts'
        def _new_ulid(prefix):
            alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
            ms = int(time.time() * 1000)
            # 26 chars base32; approximate
            v = ms
            chars = []
            for _ in range(10):
                chars.append(alphabet[v % 32])
                v //= 32
            import random
            rand = random.SystemRandom()
            for _ in range(16):
                chars.append(alphabet[rand.randrange(32)])
            return prefix + "".join(reversed(chars))[:26]

        op_row = {
            "id": _new_ulid("wpo_"),
            "site_id": site_id,
            "post_id": None,
            "operation": "get_posts",
            "status": "queued",
            "request_payload": {"use_cache": False, "filters": {"wp_post_type": wp_post_type, "status": status, "search": search}, "api_key_id": chosen_key.get("id")},
            "response_payload": None,
            "http_status": None,
            "error": None,
            "started_at": None,
            "finished_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
            "api_key_id": chosen_key.get("id")
        }
        ops.append(op_row)
        _save("post_operations.json", ops)

        # Transition queued -> running
        op_row["status"] = "running"
        op_row["started_at"] = _now_iso()
        op_row["updated_at"] = op_row["started_at"]
        _save("post_operations.json", ops)

        if site.get("status") != "active":
            op_row["status"] = "failed"
            op_row["http_status"] = None
            op_row["error"] = {"code": "SITE_NOT_ACTIVE", "message": "wp_sites.status must be 'active' for outbound WordPress calls."}
            op_row["finished_at"] = _now_iso()
            op_row["updated_at"] = op_row["finished_at"]
            _save("post_operations.json", ops)
            # Continue serving from cache even if refresh failed (consistent with "locally tracked posts")
        else:
            # Offline server: we cannot actually call WP REST API. Mark as cancelled (legal transition from running).
            op_row["status"] = "cancelled"
            op_row["response_payload"] = {"note": "Offline mode: remote refresh not executed."}
            op_row["finished_at"] = _now_iso()
            op_row["updated_at"] = op_row["finished_at"]
            _save("post_operations.json", ops)

    # --- Read + filter cached posts ---
    posts = _load("wp_posts.json")
    rows = [p for p in posts if isinstance(p, dict) and p.get("site_id") == site_id]

    if wp_post_type is not None:
        rows = [p for p in rows if p.get("wp_post_type") == wp_post_type]
    if status is not None:
        rows = [p for p in rows if p.get("status") == status]

    if search:
        q = search.strip().lower()
        if q:
            def _hay(p):
                parts = []
                for k in ("title", "slug", "content", "excerpt", "wp_link"):
                    v = p.get(k)
                    if isinstance(v, str):
                        parts.append(v.lower())
                return "\n".join(parts)
            rows = [p for p in rows if q in _hay(p)]

    # Sorting (handle missing/na datetimes safely; avoid naive/aware comparisons)
    def _sort_key(p):
        if sort_by in ("created_at", "updated_at", "remote_modified_at", "last_synced_at"):
            dt = _parse_dt_any(p.get(sort_by))
            # Put None at the end for desc, at the beginning for asc by using sentinel
            if dt is None:
                # sentinel far past or far past? We'll use epoch for asc, far future for desc
                if sort_order == "asc":
                    dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
                else:
                    dt = datetime.datetime(9999, 12, 31, tzinfo=datetime.timezone.utc)
            return dt
        if sort_by in ("title", "slug"):
            v = p.get(sort_by)
            if not isinstance(v, str):
                v = ""
            return v.casefold()
        return ""

    reverse = (sort_order == "desc")
    try:
        rows.sort(key=_sort_key, reverse=reverse)
    except Exception:
        # If a weird value sneaks in, fail gracefully
        return _err("VALIDATION_ERROR", "Unable to sort results due to invalid data in store.", field="sort_by")

    # Cursor pagination: opaque base64 of {"i": offset, "sb": sort_by, "so": sort_order}
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
            if obj.get("sb") != sort_by or obj.get("so") != sort_order:
                return _err("VALIDATION_ERROR", "Cursor does not match requested sort order.", field="cursor")
            offset = obj.get("i")
            if not isinstance(offset, int) or offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = {"i": next_offset, "sb": sort_by, "so": sort_order}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "posts": page,
        "site_id": site_id,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "use_cache": use_cache,
            "performed_refresh": performed_refresh,
            "latency_ms": latency_ms
        }
    }

def update_post(post_id, title=None, content=None, excerpt=None, slug=None, author_wp_user_id=None, status=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0552000" if __import__("os").path.isdir("./environment_mix/0552000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _parse_dt_any(v):
        if not v or not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            else:
                dt = dt.astimezone(datetime.timezone.utc)
            return dt
        except Exception:
            return None

    # --- Validate inputs ---
    if not isinstance(post_id, str) or not re.match(r"^wpp_[0-9A-HJKMNP-TV-Z]{26}$", post_id):
        return _err("VALIDATION_ERROR", "post_id must be a valid ULID with prefix 'wpp_'.", field="post_id")

    if title is not None and (not isinstance(title, str) or not title.strip()):
        return _err("VALIDATION_ERROR", "title must be a non-empty string when provided.", field="title")
    if content is not None and not isinstance(content, str):
        return _err("VALIDATION_ERROR", "content must be a string when provided.", field="content")
    if excerpt is not None and not isinstance(excerpt, str):
        return _err("VALIDATION_ERROR", "excerpt must be a string when provided.", field="excerpt")
    if slug is not None and not isinstance(slug, str):
        return _err("VALIDATION_ERROR", "slug must be a string when provided.", field="slug")
    if author_wp_user_id is not None and (not isinstance(author_wp_user_id, int) or author_wp_user_id <= 0):
        return _err("VALIDATION_ERROR", "author_wp_user_id must be a positive integer when provided.", field="author_wp_user_id")
    if status is not None and (not isinstance(status, str) or status not in ("draft", "published", "scheduled", "trashed")):  # tool enum
        return _err("VALIDATION_ERROR", "status must be one of: draft, published, scheduled, trashed.", field="status")

    if all(v is None for v in (title, content, excerpt, slug, author_wp_user_id, status)):
        return _err("VALIDATION_ERROR", "At least one field must be provided to update.", field="post_id")

    # --- Auth (ambient) + rate limit (mutations included) ---
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str)]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available.")

    ops = _load("post_operations.json")
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    window_start = now_dt - datetime.timedelta(seconds=60)

    chosen_key = None
    chosen_count = None
    for k in active_keys:
        rl = k.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1 or rl > 6000:
            continue
        kid = k.get("id")
        cnt = 0
        for o in ops:
            if not isinstance(o, dict):
                continue
            if o.get("api_key_id") != kid:
                continue
            ts = _parse_dt_any(o.get("created_at"))
            if ts is not None and ts >= window_start:
                cnt += 1
        if cnt < rl:
            if chosen_key is None or cnt < chosen_count:
                chosen_key, chosen_count = k, cnt

    if chosen_key is None:
        return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=60)

    now_iso = _now_iso()
    for kk in api_keys:
        if isinstance(kk, dict) and kk.get("id") == chosen_key.get("id"):
            kk["last_used_at"] = now_iso
            kk["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # --- Find post ---
    posts = _load("wp_posts.json")
    post = None
    for p in posts:
        if isinstance(p, dict) and p.get("id") == post_id:
            post = p
            break
    if post is None:
        return _err("NOT_FOUND", "Post not found.", post_id=post_id)

    site_id = post.get("site_id")
    sites = _load("wp_sites.json")
    site = None
    for s in sites:
        if isinstance(s, dict) and s.get("id") == site_id:
            site = s
            break
    if site is None:
        return _err("NOT_FOUND", "Site for post not found.", site_id=site_id, post_id=post_id)

    # --- Create operation row: update_post queued->running->(succeeded|failed|cancelled) ---
    def _new_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[v % 32])
            v //= 32
        import random
        rand = random.SystemRandom()
        for _ in range(16):
            chars.append(alphabet[rand.randrange(32)])
        return prefix + "".join(reversed(chars))[:26]

    op_row = {
        "id": _new_ulid("wpo_"),
        "site_id": site_id,
        "post_id": post_id,
        "operation": "update_post",
        "status": "queued",
        "request_payload": {
            "api_key_id": chosen_key.get("id"),
            "updates": {k: v for k, v in {
                "title": title, "content": content, "excerpt": excerpt, "slug": slug,
                "author_wp_user_id": author_wp_user_id, "status": status
            }.items() if v is not None}
        },
        "response_payload": None,
        "http_status": None,
        "error": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now_iso,
        "updated_at": now_iso,
        "api_key_id": chosen_key.get("id")
    }
    ops.append(op_row)
    _save("post_operations.json", ops)

    # queued -> running
    op_row["status"] = "running"
    op_row["started_at"] = _now_iso()
    op_row["updated_at"] = op_row["started_at"]
    _save("post_operations.json", ops)

    # Must not use non-active site for outbound calls; log failed
    if site.get("status") != "active":
        op_row["status"] = "failed"
        op_row["error"] = {"code": "SITE_NOT_ACTIVE", "message": "wp_sites.status must be 'active' for outbound WordPress calls."}
        op_row["finished_at"] = _now_iso()
        op_row["updated_at"] = op_row["finished_at"]
        _save("post_operations.json", ops)
        return _err("INVALID_TRANSITION", "Cannot update remote WordPress post because site connection is not active.", site_id=site_id, site_status=site.get("status"))

    # Must reference existing wp_posts row OR provide known (site_id, wp_post_id) mapping.
    # This tool only accepts post_id, so mapping is inherently present; but ensure wp_post_id exists to update remote.
    if post.get("wp_post_id") is None or not isinstance(post.get("wp_post_id"), int) or post.get("wp_post_id") <= 0:
        op_row["status"] = "failed"
        op_row["error"] = {"code": "MISSING_REMOTE_MAPPING", "message": "No known (site_id, wp_post_id) mapping for this post; cannot update remote WordPress post."}
        op_row["finished_at"] = _now_iso()
        op_row["updated_at"] = op_row["finished_at"]
        _save("post_operations.json", ops)
        return _err("CONFLICT", "Cannot update because wp_post_id mapping is missing for this post.", post_id=post_id)

    # --- Apply local updates first, set sync_pending then complete with offline simulated success ---
    prev_status = post.get("status")
    # Transition local status -> sync_pending if allowed
    transitions = {
        "draft": ["sync_pending", "trashed"],
        "published": ["sync_pending", "trashed"],
        "scheduled": ["sync_pending", "trashed"],
        "trashed": ["sync_pending"],
        "sync_pending": ["draft", "published", "scheduled", "sync_error"],
        "sync_error": ["sync_pending", "trashed"]
    }
    if prev_status not in transitions or "sync_pending" not in transitions.get(prev_status, []):
        op_row["status"] = "failed"
        op_row["error"] = {"code": "INVALID_LOCAL_TRANSITION", "message": "Local post status cannot transition to sync_pending from current state."}
        op_row["finished_at"] = _now_iso()
        op_row["updated_at"] = op_row["finished_at"]
        _save("post_operations.json", ops)
        return _err("INVALID_TRANSITION", "Local post status cannot transition to sync_pending.", from_status=prev_status, to_status="sync_pending")

    # Mutate post row
    if title is not None:
        post["title"] = title
    if content is not None:
        post["content"] = content
    if excerpt is not None:
        post["excerpt"] = excerpt
    if slug is not None:
        post["slug"] = slug
    if author_wp_user_id is not None:
        post["author_wp_user_id"] = author_wp_user_id

    post["status"] = "sync_pending"
    post["updated_at"] = _now_iso()
    post["last_error"] = None
    _save("wp_posts.json", posts)

    # Offline server: simulate WP update by completing sync with mapped wp_status and remote_modified_at
    # Map local -> remote
    local_to_wp = {"draft": "draft", "published": "publish", "scheduled": "future", "trashed": "trash"}
    final_local = None
    final_wp_status = None
    if status is not None:
        final_local = status
        final_wp_status = local_to_wp.get(status)
    else:
        # Keep existing publish state if already one of allowed; otherwise default to draft
        if post.get("status") in ("draft", "published", "scheduled", "trashed"):
            final_local = post.get("status")
        else:
            final_local = "draft"
        # But we set sync_pending above; choose based on previous if applicable
        if prev_status in ("draft", "published", "scheduled", "trashed"):
            final_local = prev_status
        final_wp_status = local_to_wp.get(final_local, "draft")

    # Must not remain sync_pending on success
    finished_iso = _now_iso()
    post["status"] = final_local if final_local in ("draft", "published", "scheduled", "trashed") else "draft"
    post["wp_status"] = final_wp_status
    post["remote_modified_at"] = finished_iso
    post["last_synced_at"] = finished_iso
    post["updated_at"] = finished_iso
    post["last_error"] = None
    _save("wp_posts.json", posts)

    op_row["status"] = "succeeded"
    op_row["http_status"] = 200
    op_row["response_payload"] = {"note": "Offline mode: remote update simulated.", "wp_post_id": post.get("wp_post_id")}
    op_row["finished_at"] = finished_iso
    op_row["updated_at"] = finished_iso
    _save("post_operations.json", ops)

    latency_ms = int((time.time() - t0) * 1000)
    return {"post": post, "operation_id": op_row["id"], "meta": {"latency_ms": latency_ms}}

