def get_sites(status=None, search=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0552000" if __import__("os").path.isdir("./environment_mix/0552000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # --- Auth: must have at least one active api_keys row available (ambient auth) ---
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available.")
    # Choose a deterministic "used key" for rate limiting/audit
    active_keys.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
    key = active_keys[0]
    key_id = key.get("id")

    # --- Rate limit per minute (per key) ---
    rate_limit = key.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int) or rate_limit < 1 or rate_limit > 6000:
        # Store corruption; treat as unauthorized to avoid unbounded access
        return _err("UNAUTHORIZED", "API key configuration invalid.")

    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)

    ops = _load("post_operations.json")
    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    recent = 0
    for op in ops:
        if not isinstance(op, dict): 
            continue
        if op.get("request_payload", {}).get("api_key_id") != key_id:
            continue
        ts = _parse_dt(op.get("created_at"))
        if ts and ts >= window_start:
            recent += 1

    if recent >= rate_limit:
        # SHOULD NOT enqueue queued operations: do not create operation rows
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rate_limit, window_seconds=60)

    # --- Validate inputs ---
    if status is not None and status not in ("active", "disabled", "error"):
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")
    if search is not None and not isinstance(search, str):
        return _err("VALIDATION_ERROR", "search must be a string.", field="search")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if sort_by is None:
        sort_by = "created_at"
    if sort_by not in ("created_at", "updated_at", "name", "base_url", "last_healthcheck_at"):
        return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by")
    if sort_order is None:
        sort_order = "asc"
    if sort_order not in ("asc", "desc"):
        return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order")

    # --- Read/filter ---
    sites = _load("wp_sites.json")
    rows = []
    q = (search or "").strip().lower() if isinstance(search, str) else ""
    for s in sites:
        if not isinstance(s, dict):
            continue
        if status is not None and s.get("status") != status:
            continue
        if q:
            hay = f"{s.get('name','')} {s.get('base_url','')}".lower()
            if q not in hay:
                continue
        rows.append(s)

    # --- Sort ---
    def _sort_key(r):
        v = r.get(sort_by)
        if v is None:
            return ""
        if isinstance(v, str):
            return v.lower() if sort_by in ("name", "base_url") else v
        return v

    reverse = (sort_order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # --- Cursor pagination ---
    # Cursor is base10 offset string "o:<int>"
    offset = 0
    if cursor:
        m = re.fullmatch(r"o:(\d+)", cursor.strip())
        if not m:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        offset = int(m.group(1))
        if offset < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor offset.", field="cursor")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"o:{next_offset}" if has_more else None

    # --- Record request as operation (reads included) ---
    # Use operation='get_posts' as closest existing enum; include endpoint for disambiguation.
    iso_now = now.replace(microsecond=0).isoformat() + "Z"
    op_row = {
        "id": None,
        "site_id": page[0]["id"] if page else (rows[0]["id"] if rows else (sites[0]["id"] if sites else "unknown")),
        "post_id": None,
        "operation": "get_posts",
        "status": "succeeded",
        "request_payload": {
            "endpoint": "get_sites",
            "api_key_id": key_id,
            "filters": {
                "status": status,
                "search": search,
                "limit": limit,
                "cursor": cursor,
                "sort_by": sort_by,
                "sort_order": sort_order
            }
        },
        "response_payload": {
            "count": len(page),
            "total": total,
            "has_more": has_more
        },
        "http_status": 200,
        "error": None,
        "started_at": iso_now,
        "finished_at": iso_now,
        "created_at": iso_now,
        "updated_at": iso_now
    }

    # Generate ULID-like id: "op_" + 26 crockford base32 chars
    def _ulid(prefix):
        import os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 16 bytes -> 26 chars in base32 (130 bits; we truncate)
        b = os.urandom(16)
        n = int.from_bytes(b, "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n & 31])
            n >>= 5
        return prefix + "".join(reversed(out))
    op_row["id"] = _ulid("op_")
    ops.append(op_row)
    _save("post_operations.json", ops)

    # Update api key last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = iso_now
            k["updated_at"] = k.get("updated_at") or iso_now
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "sites": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "cursor": cursor,
            "latency_ms": latency_ms
        }
    }

