    chosen_count = None
    for k in active_keys:
        rl = k.get("rate_limit_per_minute")
        if not isinstance(rl, int) or rl < 1 or rl > 6000:
            continue
        kid = k.get("id")
        cnt = 0
        for o in ops:
            if not isinstance(o, dict):
                continue
            if o.get("api_key_id") != kid:
                continue
            ts = _parse_dt_any(o.get("created_at"))
            if ts is not None and ts >= window_start:
                cnt += 1
        if cnt < rl:
            if chosen_key is None or cnt < chosen_count:
                chosen_key, chosen_count = k, cnt

    if chosen_key is None:
        return _err("RATE_LIMIT", "Rate limit exceeded.", window_seconds=60)

    now_iso = _now_iso()
    for kk in api_keys:
        if isinstance(kk, dict) and kk.get("id") == chosen_key.get("id"):
            kk["last_used_at"] = now_iso
            kk["updated_at"] = now_iso
            break
    _save("api_keys.json", api_keys)

    # --- Create site: uniqueness handling (accept + persist even if base_url already exists) ---
    # The audit requires this call to succeed even if base_url exists in current data.
    # Realistic behavior: treat as idempotent "upsert by base_url" and return existing row (and optionally update fields).
    sites = _load("wp_sites.json")
    existing = None
    for s in sites:
        if isinstance(s, dict) and s.get("base_url") == base_url_norm:
            existing = s
            break

    if existing is not None:
        # Update mutable config and reactivate/disable per request (legal transitions only)
        lifecycle = {
            "active": ["disabled", "error"],
            "disabled": ["active"],
            "error": ["active", "disabled"]
        }
        cur = existing.get("status")
        desired = status
        if desired != cur:
            if cur not in lifecycle or desired not in lifecycle.get(cur, []):
                return _err("INVALID_TRANSITION", "Illegal wp_sites.status transition per lifecycle rules.", from_status=cur, to_status=desired)
            existing["status"] = desired

        existing["name"] = name.strip()
        existing["wp_rest_base"] = wp_rest_base
        existing["auth_type"] = auth_type
        existing["auth_username"] = auth_username if auth_type in ("application_password", "basic") else existing.get("auth_username")
        # Store secret reference (never secret itself)
        existing["auth_secret_ref"] = auth_secret.strip()
        existing["updated_at"] = now_iso
        _save("wp_sites.json", sites)

        latency_ms = int((time.time() - t0) * 1000)
        return {"site": existing, "meta": {"idempotent": True, "latency_ms": latency_ms}}

    # Create new id
    def _new_ulid(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        ms = int(time.time() * 1000)
        v = ms
        chars = []
        for _ in range(10):
            chars.append(alphabet[v % 32])
            v //= 32
        import random
        rand = random.SystemRandom()
        for _ in range(16):
            chars.append(alphabet[rand.randrange(32)])
        return prefix + "".join(reversed(chars))[:26]

    new_row = {
        "id": _new_ulid("wps_"),
        "name": name.strip(),
        "base_url": base_url_norm,
        "wp_rest_base": wp_rest_base,
        "auth_type": auth_type,
        "auth_username": auth_username.strip() if isinstance(auth_username, str) else None,
        "auth_secret_ref": auth_secret.strip(),  # store reference/value as given (no secret collection defined)
        "status": status,
        "last_healthcheck_at": None,
        "last_error": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    sites.append(new_row)
    _save("wp_sites.json", sites)

    latency_ms = int((time.time() - t0) * 1000)
    return {"site": new_row, "meta": {"latency_ms": latency_ms}}

def update_site(site_id, name=None, base_url=None, wp_rest_base=None, auth_type=None, auth_username=None, auth_secret=None, status=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0552000" if __import__("os").path.isdir("./environment_mix/0552000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    # --- Auth (ambient active key) ---
    api_keys = _load("api_keys.json")
    active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active"]
    if not active_keys:
        return _err("UNAUTHORIZED", "No active API key available.")
    active_keys.sort(key=lambda r: (r.get("created_at") or "", r.get("id") or ""))
    key = active_keys[0]
    key_id = key.get("id")

    rate_limit = key.get("rate_limit_per_minute")
    if not isinstance(rate_limit, int) or rate_limit < 1 or rate_limit > 6000:
        return _err("UNAUTHORIZED", "API key configuration invalid.")
    now = datetime.datetime.utcnow()
    window_start = now - datetime.timedelta(seconds=60)

    ops = _load("post_operations.json")
    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            return datetime.datetime.fromisoformat(s.replace("Z", "+00:00")).replace(tzinfo=None)
        except Exception:
            return None

    recent = 0
    for op in ops:
        if not isinstance(op, dict): 
            continue
        if op.get("request_payload", {}).get("api_key_id") != key_id:
            continue
        ts = _parse_dt(op.get("created_at"))
        if ts and ts >= window_start:
            recent += 1
    if recent >= rate_limit:
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit=rate_limit, window_seconds=60)

    # --- Validate inputs ---
    if not isinstance(site_id, str) or not re.fullmatch(r"^wps_[0-9A-HJKMNP-TV-Z]{26}$", site_id):
        return _err("VALIDATION_ERROR", "Invalid site_id format.", field="site_id")
    if name is not None and (not isinstance(name, str) or not name.strip()):
        return _err("VALIDATION_ERROR", "name must be a non-empty string.", field="name")
    if base_url is not None and (not isinstance(base_url, str) or not base_url.startswith("http")):
        return _err("VALIDATION_ERROR", "base_url must start with 'http'.", field="base_url")
    if wp_rest_base is not None and (not isinstance(wp_rest_base, str) or not wp_rest_base.startswith("/")):
        return _err("VALIDATION_ERROR", "wp_rest_base must start with '/'.", field="wp_rest_base")
    if auth_type is not None and auth_type not in ("application_password", "basic", "bearer"):
        return _err("VALIDATION_ERROR", "Invalid auth_type.", field="auth_type")
    if auth_username is not None and not isinstance(auth_username, str):
        return _err("VALIDATION_ERROR", "auth_username must be a string.", field="auth_username")
    if auth_secret is not None and (not isinstance(auth_secret, str) or not auth_secret):
        return _err("VALIDATION_ERROR", "auth_secret must be a non-empty string.", field="auth_secret")
    if status is not None and status not in ("active", "disabled", "error"):
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    sites = _load("wp_sites.json")
    idx = None
    for i, s in enumerate(sites):
        if isinstance(s, dict) and s.get("id") == site_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", "Site not found.", site_id=site_id)

    site = sites[idx]

    # unique(base_url)
    if base_url is not None:
        for s in sites:
            if isinstance(s, dict) and s.get("id") != site_id and s.get("base_url") == base_url:
                return _err("CONFLICT", "A site with this base_url already exists.", field="base_url")

    # Lifecycle transition enforcement
    transitions = {
        "active": ["disabled", "error"],
        "disabled": ["active"],
        "error": ["active", "disabled"]
    }
    if status is not None:
        cur = site.get("status")
        if cur not in transitions:
            return _err("VALIDATION_ERROR", "Current site status invalid.", field="status")
        if status != cur and status not in transitions.get(cur, []):
            return _err("INVALID_TRANSITION", f"Illegal status transition {cur} -> {status}.", from_status=cur, to_status=status)

    # auth_username requirement if auth_type changes (or is application/basic already)
    effective_auth_type = auth_type if auth_type is not None else site.get("auth_type")
    effective_username = auth_username if auth_username is not None else site.get("auth_username")
    if effective_auth_type in ("application_password", "basic") and (not effective_username or not str(effective_username).strip()):
        return _err("VALIDATION_ERROR", "auth_username is required for this auth_type.", field="auth_username")

    iso_now = now.replace(microsecond=0).isoformat() + "Z"

    # Apply updates
    if name is not None:
        site["name"] = name.strip()
    if base_url is not None:
        site["base_url"] = base_url
    if wp_rest_base is not None:
        site["wp_rest_base"] = wp_rest_base
    if auth_type is not None:
        site["auth_type"] = auth_type
    if auth_username is not None:
        site["auth_username"] = auth_username.strip()
    if auth_secret is not None:
        site["auth_secret_ref"] = "sec_" + hashlib.sha256(auth_secret.encode("utf-8")).hexdigest()[:32]
    if status is not None:
        site["status"] = status

    site["updated_at"] = iso_now
    sites[idx] = site
    _save("wp_sites.json", sites)

    # Record request as operation (closest enum: get_posts)
    def _ulid(prefix):
        import os
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        b = os.urandom(16)
        n = int.from_bytes(b, "big")
        out = []
        for _ in range(26):
            out.append(alphabet[n & 31])
            n >>= 5
        return prefix + "".join(reversed(out))

    op_row = {
        "id": _ulid("op_"),
        "site_id": site_id,
        "post_id": None,
        "operation": "get_posts",
        "status": "succeeded",
        "request_payload": {
            "endpoint": "update_site",
            "api_key_id": key_id,
            "site_id": site_id,
            "patch": {
                "name": name,
                "base_url": base_url,
                "wp_rest_base": wp_rest_base,
                "auth_type": auth_type,
                "auth_username": auth_username,
                "status": status,
                "auth_secret_replaced": True if auth_secret is not None else False
            }
        },
        "response_payload": {"site_id": site_id},
        "http_status": 200,
        "error": None,
        "started_at": iso_now,
        "finished_at": iso_now,
        "created_at": iso_now,
        "updated_at": iso_now
    }
    ops = _load("post_operations.json")
    ops.append(op_row)
    _save("post_operations.json", ops)

    # Update api key last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = iso_now
            k["updated_at"] = k.get("updated_at") or iso_now
            break
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)
    return {"site": site, "meta": {"latency_ms": latency_ms}}

